#!/usr/bin/env python3
"""
Batch processor for Phase 02c code resolution.
Uses filesystem tools and grep to find code locations.
"""
import json
import re
import os
from pathlib import Path

# Load queue
with open('outputs/02c_ASYNC_QUEUE_W3B4_1771254431.json', 'r') as f:
    queue = json.load(f)

items = queue['items']
results = []

# Target workspace
TARGET_WS = Path('/home/gohan/runners/security-agent-2/_work/security-agent/security-agent/target_workspace')

# Key function patterns to search for
FUNCTION_PATTERNS = {
    'VerifyDataColumnSidecar': 'beacon-chain/core/peerdas/p2p_interface.go',
    'VerifyDataColumnSidecarInclusionProof': 'beacon-chain/core/peerdas/p2p_interface.go',
    'VerifyDataColumnsSidecarKZGProofs': 'beacon-chain/core/peerdas/p2p_interface.go',
    'ComputeSubnetForDataColumnSidecar': 'beacon-chain/core/peerdas',
}

# Pre-load known files
file_cache = {}

def extract_function_info(file_path, function_name):
    """Extract function location and body from file."""
    if file_path not in file_cache:
        try:
            with open(TARGET_WS / file_path, 'r') as f:
                file_cache[file_path] = f.readlines()
        except Exception as e:
            print(f"Error reading {file_path}: {e}")
            return None

    lines = file_cache[file_path]

    # Find function declaration
    pattern = rf'^func\s+{function_name}\s*\('
    for i, line in enumerate(lines):
        if re.search(pattern, line):
            # Found function start
            start_line = i + 1  # 1-indexed

            # Find function end (simplified - count braces)
            brace_count = 0
            end_line = start_line
            for j in range(i, len(lines)):
                brace_count += lines[j].count('{') - lines[j].count('}')
                if brace_count == 0 and j > i:
                    end_line = j + 1
                    break

            return {
                'file': file_path,
                'symbol': function_name,
                'line_range': {'start': start_line, 'end': end_line},
                'role': 'primary'
            }

    return None

def infer_function_from_item(item):
    """Infer the main function under test from item fields."""
    # Check validation_layers
    val_layers = item.get('reachability', {}).get('validation_layers', [])
    for layer in val_layers:
        if 'verify_data_column_sidecar' in layer.lower():
            if 'inclusion_proof' in layer.lower():
                return 'VerifyDataColumnSidecarInclusionProof'
            elif 'kzg_proofs' in layer.lower() or 'kzg_proof' in layer.lower():
                return 'VerifyDataColumnsSidecarKZGProofs'
            else:
                return 'VerifyDataColumnSidecar'

    # Check title and test_procedure
    title = item.get('title', '').lower()
    test_proc = item.get('test_procedure', '').lower()

    if 'verify_data_column_sidecar_inclusion_proof' in title or 'verify_data_column_sidecar_inclusion_proof' in test_proc:
        return 'VerifyDataColumnSidecarInclusionProof'
    elif 'verify_data_column_sidecar_kzg_proof' in title or 'verify_data_column_sidecar_kzg_proof' in test_proc:
        return 'VerifyDataColumnsSidecarKZGProofs'
    elif 'verify_data_column_sidecar' in title or 'verify_data_column_sidecar' in test_proc:
        return 'VerifyDataColumnSidecar'
    elif 'compute_subnet_for_data_column_sidecar' in title or 'compute_subnet_for_data_column_sidecar' in test_proc:
        return 'ComputeSubnetForDataColumnSidecar'

    # Fallback: gossip validation
    if 'gossip' in title or 'gossip' in test_proc:
        return 'ValidateDataColumn'  # Gossip validator function

    return None

print(f"Processing {len(items)} items...")

# Process each item
for idx, item in enumerate(items):
    check_id = item.get('check_id', f'UNKNOWN-{idx}')

    # Infer function
    func_name = infer_function_from_item(item)

    if func_name is None:
        # No element found - mark as specification_only
        result = {
            'check_id': check_id,
            'code_scope': {
                'locations': [],
                'resolution_status': 'specification_only',
                'resolution_error': 'No specific code element identified in checklist item'
            },
            'code_excerpt': None
        }
    else:
        # Try to find function
        file_path = FUNCTION_PATTERNS.get(func_name)

        if file_path:
            func_info = extract_function_info(file_path, func_name)

            if func_info:
                result = {
                    'check_id': check_id,
                    'code_scope': {
                        'locations': [func_info],
                        'resolution_status': 'resolved',
                        'inferred_element': func_name
                    },
                    'code_excerpt': None  # Will be populated in next step
                }
            else:
                result = {
